#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"; source "$ROOT/scripts/mig_devices.sh"; MIGS=("${MIG3}" "${MIG4}" "${MIG5}" "${MIG6}")
PYTHON="${PYTHON:-$(command -v python)}"
SUBJECTS=(dog2 teapot); LOG="$ROOT/logs/ablations/task_f_prior"; STATUS="$ROOT/outputs/ablations/task_f_prior_training"; mkdir -p "$LOG" "$STATUS"; unlink "$STATUS/FAILED" 2>/dev/null||true;unlink "$STATUS/SUCCESS" 2>/dev/null||true
echo "TASK_F_START=$(date --iso-8601=seconds) TRAIN_JOBS=2 ETA_MINUTES=8-15";start=$(date +%s)
pids=(); for i in "${!SUBJECTS[@]}";do s="${SUBJECTS[$i]}"; CUDA_VISIBLE_DEVICES="${MIGS[$i]}" bash "$ROOT/scripts/jobs/train_lora_variant.sh" "$s" 16 0 off "outputs/ablations/task_f_prior_training/${s}_prior_off" >"$LOG/train_${s}_off.log" 2>&1&pids+=("$!");done;code=0;for p in "${pids[@]}";do if ! wait "$p";then code=1;fi;done;if ((code));then touch "$STATUS/FAILED";exit 1;fi
tasks=("dog2 off" "teapot off" "dog2 on" "teapot on");pids=()
for i in "${!tasks[@]}";do read -r s prior<<<"${tasks[$i]}";if [[ "$prior" == off ]];then w="outputs/ablations/task_f_prior_training/${s}_prior_off/pytorch_lora_weights.safetensors";else w="outputs/training/lora/${s}_lora_r16_s800_seed42/pytorch_lora_weights.safetensors";fi;refs=$("${PYTHON}" -c "import yaml;print(yaml.safe_load(open('$ROOT/configs/main_subjects.yaml'))['subjects']['$s']['expected_images'])");CUDA_VISIBLE_DEVICES="${MIGS[$i]}" "${PYTHON}" "$ROOT/src/inference/generate_lora_variant.py" --project-root "$ROOT" --subject "$s" --weights "$w" --output-root "outputs/experiments/task_f_prior/prior_${prior}" --experiment task_f_prior --variant "lora_prior_${prior}" --rank 16 --n-refs "$refs" --prior "$prior" --resume >"$LOG/generate_${s}_${prior}.log" 2>&1&pids+=("$!");done;code=0;for p in "${pids[@]}";do if ! wait "$p";then code=1;fi;done;if ((code));then touch "$STATUS/FAILED";exit 1;fi
touch "$STATUS/SUCCESS";finish=$(date +%s);echo "runtime_seconds=$((finish-start))">"$LOG/runtime.txt";echo "TASK_F_COMPLETE=$(date --iso-8601=seconds)"
